-- Seeds real, publicly known EV charging locations in Uruguay from
-- OpenChargeMap (CC BY 4.0, api.openchargemap.io, countrycode=UY) so the
-- community stations list isn't empty for new users. Attributed to the
-- maintainer's account and marked verified so they render "Oficial" (0020)
-- instead of looking like an anonymous claim. ocm_id is kept so a future
-- re-sync can UPDATE these rows instead of re-inserting duplicates.
-- Apply with `npx supabase db push`.

alter table public.charging_stations
  add column ocm_id integer,
  add column ocm_last_synced_at timestamptz;

-- A single OCM POI can list several connector variants at the same
-- physical location (e.g. a CCS2 and a Tipo 2 post, or two CCS2 posts at
-- different power) — each becomes its own row, so uniqueness is per
-- (poi, connector, power), not per poi alone.
create unique index charging_stations_ocm_id_idx
  on public.charging_stations (ocm_id, connector, max_power_kw)
  where ocm_id is not null;

-- Networks discovered in OCM with no existing charging_networks row.
-- Instructions left null (unknown) — a moderator can fill them in later,
-- same as 'otro' already has no instructions.
insert into public.charging_networks (slug, name, country, instructions, sort_order) values
  ('eve-move', 'Eve Move', 'UY', null, 15),
  ('nes',      'NES Charge', 'UY', null, 16),
  ('umt',      'UMT EV Charge', 'UY', null, 17);

-- "Ancap Rocha", already submitted by a community member, is the same
-- physical station as OCM #260138 — backfill the OCM link and any fields
-- the community submission left blank, without touching what they entered.
update public.charging_stations
set
  ocm_id = 260138,
  ocm_last_synced_at = '2025-05-30T03:39:00Z',
  address = coalesce(address, 'Ruta 9 Coronel Leonardo Olivera'),
  lat = coalesce(lat, -34.496425),
  lng = coalesce(lng, -54.327509),
  max_power_kw = coalesce(max_power_kw, 60)
where name = 'Ancap Rocha' and network = 'ute' and ocm_id is null;

-- Bulk seed. Disable the daily anti-spam trigger (0009) for the duration of
-- this insert — it fires unconditionally regardless of auth.uid(), unlike
-- prevent_unauthorized_verify (0020) which already special-cases the no-JWT
-- migration/bootstrap path, so 209 rows under one user_id would
-- otherwise trip the 20/day cap partway through.
alter table public.charging_stations disable trigger limit_charging_stations_per_day;

